hooks.command:
python -c "import pathlib,runpy,sys
try:
 roots=(pathlib.Path.cwd(),*pathlib.Path.cwd().parents)
 root=next((p for p in roots if (p/'.git').exists()),None)
 if root is None: sys.exit(2)
 target=root/'hooks'/sys.argv[1]
 if not target.is_file(): sys.exit(2)
 sys.argv=[str(target),*sys.argv[2:]]
 runpy.run_path(str(target),run_name='__main__')
except Exception:
 sys.stderr.write('Hook launch failed; restore the complete verified gate set.\n')
 sys.exit(2)
" reinject_agents_policy.py --client gemini

